#pragma once

namespace Nexo::Themes {

// Built-in Nexo themes, generated by
// Resources/nexo/themes/make_themes.py and shipped in nexo.qrc.
struct Theme {
	QString id;
	QString name;
	QColor accent;
	QColor background;
};

[[nodiscard]] const std::vector<Theme> &List();

// Id of the applied Nexo theme, empty if another theme is in use.
[[nodiscard]] QString CurrentId();

// Applies and keeps the theme. Returns false if it could not be loaded.
bool Apply(const QString &id);

} // namespace Nexo::Themes
